import { createTool, deleteTool } from '../services/toolsService';
import { updateStats } from '../services/statsService';
import { updateSettings } from '../services/settingsService';

export const useAdminActions = ({ onRefresh, setMessage, setFormData }) => {
  const addTool = async (formData) => {
    try {
      await createTool(formData);
      setMessage('Tool added successfully');
      setFormData({});
      onRefresh();
    } catch (error) {
      setMessage('Error adding tool');
    }
  };

  const removeTool = async (id) => {
    try {
      await deleteTool(id);
      setMessage('Tool deleted successfully');
      onRefresh();
    } catch (error) {
      setMessage('Error deleting tool');
    }
  };

  const saveStats = async (formData) => {
    try {
      await updateStats(formData);
      setMessage('Stats updated successfully');
      onRefresh();
    } catch (error) {
      setMessage('Error updating stats');
    }
  };

  const saveSettings = async (formData) => {
    try {
      await updateSettings(formData);
      setMessage('Settings updated successfully');
      onRefresh();
    } catch (error) {
      setMessage('Error updating settings');
    }
  };

  return { addTool, removeTool, saveStats, saveSettings };
};
